function accentInk(color){
  const rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);
  const light=rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722;
  // sRGB luminance + .05 for the two preferred text inks below.
  const darkContrast=(light+.05)/.06613424179463222,lightContrast=1.032259597572951/(light+.05);
  if(Math.max(darkContrast,lightContrast)<4.5)return light>.179?'#000000':'#ffffff';
  return darkContrast>=lightContrast?'#202320':'#fffdf7';
}
